ALTER TABLE "connectors" DROP CONSTRAINT "connectors_builtin";--> statement-breakpoint
ALTER TABLE "connectors" DROP CONSTRAINT "connectors_builtin_url";--> statement-breakpoint
ALTER TABLE "connectors" ADD CONSTRAINT "connectors_builtin" CHECK ("connectors"."builtin" IS NULL OR ((("connectors"."builtin" = 'kobe' AND "connectors"."id" = '6b6f6265-0000-4000-8000-000000000001'::uuid) OR ("connectors"."builtin" = 'git' AND "connectors"."id" = '6b6f6265-0000-4000-8000-000000000002'::uuid)) AND "connectors"."auth_kind" = 'none' AND "connectors"."credential_source" = 'member' AND "connectors"."tools_hash" IS NULL AND "connectors"."tools_snapshot" = '[]'::jsonb));--> statement-breakpoint
ALTER TABLE "connectors" ADD CONSTRAINT "connectors_builtin_url" CHECK (CASE WHEN "connectors"."builtin" IS NULL THEN "connectors"."url" NOT IN ('http://kobe-server.internal/internal/v1/mcp/kobe', 'http://kobe-server.internal/internal/v1/mcp/git') WHEN "connectors"."builtin" = 'kobe' THEN "connectors"."url" = 'http://kobe-server.internal/internal/v1/mcp/kobe' WHEN "connectors"."builtin" = 'git' THEN "connectors"."url" = 'http://kobe-server.internal/internal/v1/mcp/git' ELSE false END);